document.addEventListener('DOMContentLoaded',function(){const form=document.getElementById('collaborationForm');if(!form)return;const isEnglish=document.documentElement.lang==='en';const messages={required:isEnglish?'This field is required':'Bu alan zorunludur',invalidName:isEnglish?'Only letters and spaces allowed':'Sadece harf ve boşluk kullanılabilir',invalidEmail:isEnglish?'Please enter a valid email address':'Geçerli bir e-posta adresi giriniz',invalidPhone:isEnglish?'Please enter a valid phone number (10 digits)':'Geçerli bir telefon numarası giriniz (10 haneli)',success:isEnglish?'Form submitted successfully. Your email application will open.':'Form başarıyla gönderildi. E-posta uygulamanız açılacak.',fileTooBig:isEnglish?'File size exceeds 10MB limit':'Dosya boyutu 10MB limitini aşıyor',invalidFileType:isEnglish?'Invalid file type. Allowed: PDF, DOC, DOCX, TXT, JPG, PNG':'Geçersiz dosya türü. İzin verilenler: PDF, DOC, DOCX, TXT, JPG, PNG'};const patterns={name:/^[A-Za-zÀ-ÖØ-öø-ÿ\s]+$/,email:/^[^\s@]+@[^\s@]+\.[^\s@]+$/,phone:/^\d{10}$/};function createErrorElement(){const error=document.createElement('small');error.className='error-message';error.style.color='#dc3545';error.style.fontSize='0.85rem';error.style.marginTop='0.25rem';return error;}
function formatPhoneNumber(value){const cleaned=value.replace(/\D/g,'');const trimmed=cleaned.slice(0,10);if(trimmed.length>=6){return`(${trimmed.slice(0, 3)}) ${trimmed.slice(3, 6)}-${trimmed.slice(6)}`;}else if(trimmed.length>=3){return`(${trimmed.slice(0, 3)}) ${trimmed.slice(3)}`;}else if(trimmed.length>0){return`(${trimmed}`;}
return trimmed;}
const phoneInput=document.getElementById('phone');if(phoneInput){phoneInput.addEventListener('input',(e)=>{const start=e.target.selectionStart;const end=e.target.selectionEnd;const previousLength=e.target.value.length;e.target.value=formatPhoneNumber(e.target.value);const newLength=e.target.value.length;if(start===previousLength){e.target.setSelectionRange(newLength,newLength);}else{const cursorAdjustment=newLength-previousLength;e.target.setSelectionRange(start+cursorAdjustment,end+cursorAdjustment);}});phoneInput.addEventListener('keypress',(e)=>{if(!/\d/.test(e.key)&&e.key!=='Backspace'&&e.key!=='Delete'&&e.key!=='ArrowLeft'&&e.key!=='ArrowRight'){e.preventDefault();}});}
const fileInput=document.getElementById('attachment');const fileInfo=document.getElementById('fileInfo');if(fileInput&&fileInfo){fileInput.addEventListener('change',function(e){const file=e.target.files[0];if(!file){fileInfo.textContent='';return;}
const maxSize=10*1024*1024;if(file.size>maxSize){fileInfo.style.color='#dc3545';fileInfo.textContent=messages.fileTooBig;fileInput.value='';return;}
const allowedTypes=['application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','text/plain','image/jpeg','image/png'];if(!allowedTypes.includes(file.type)){fileInfo.style.color='#dc3545';fileInfo.textContent=messages.invalidFileType;fileInput.value='';return;}
fileInfo.style.color='#28a745';fileInfo.textContent=`${file.name} (${(file.size / (1024 * 1024)).toFixed(2)}MB)`;});}
function validateInput(input){const errorElement=input.nextElementSibling?.classList.contains('error-message')?input.nextElementSibling:createErrorElement();let isValid=true;let errorMessage='';if(input.required&&!input.value.trim()){isValid=false;errorMessage=messages.required;}
else if(input.value.trim()){switch(input.name){case'companyName':case'contactPerson':if(!patterns.name.test(input.value)){isValid=false;errorMessage=messages.invalidName;}
break;case'email':if(!patterns.email.test(input.value)){isValid=false;errorMessage=messages.invalidEmail;}
break;case'phone':const digits=input.value.replace(/\D/g,'');if(digits.length!==10){isValid=false;errorMessage=messages.invalidPhone;}
break;}}
input.style.borderColor=isValid?'#28a745':'#dc3545';input.style.backgroundColor=isValid?'#f8fff9':'#fff8f8';if(!isValid){errorElement.textContent=errorMessage;if(!input.nextElementSibling?.classList.contains('error-message')){input.insertAdjacentElement('afterend',errorElement);}}else if(input.nextElementSibling?.classList.contains('error-message')){input.nextElementSibling.remove();}
return isValid;}
form.querySelectorAll('input, textarea, select').forEach(input=>{if(input.id!=='phone'){input.addEventListener('input',()=>validateInput(input));}
input.addEventListener('blur',()=>validateInput(input));});form.addEventListener('submit',function(e){e.preventDefault();let isValid=true;form.querySelectorAll('input:not([type="file"]), textarea, select').forEach(input=>{if(!validateInput(input)){isValid=false;}});if(!isValid)return;const formData={companyName:document.getElementById('companyName').value,contactPerson:document.getElementById('contactPerson').value,email:document.getElementById('email').value,phone:document.getElementById('phone').value,industry:document.getElementById('industry').value,collaborationType:document.getElementById('collaborationType').value,message:document.getElementById('message').value};const file=fileInput?.files[0];let attachmentInfo='';if(file){attachmentInfo=isEnglish?`\n\nAttachment Information:\nFile Name: ${file.name}\nFile Size: ${(file.size / (1024 * 1024)).toFixed(2)}MB`:`\n\nDosya Bilgisi:\nDosya Adı: ${file.name}\nDosya Boyutu: ${(file.size / (1024 * 1024)).toFixed(2)}MB`;}
const emailSubject=isEnglish?`Collaboration Request - ${formData.companyName}`:`İş Birliği Talebi - ${formData.companyName}`;const emailBody=isEnglish?`
            New Collaboration Request:
            
            Company Name: ${formData.companyName}
            Contact Person: ${formData.contactPerson}
            Email: ${formData.email}
            Phone: ${formData.phone}
            Industry: ${formData.industry}
            Collaboration Type: ${formData.collaborationType}
            
            Message:
            ${formData.message}
            ${attachmentInfo}
        `:`
            Yeni İş Birliği Talebi:
            
            Firma Adı: ${formData.companyName}
            İletişim Kişisi: ${formData.contactPerson}
            E-posta: ${formData.email}
            Telefon: ${formData.phone}
            Sektör: ${formData.industry}
            İş Birliği Türü: ${formData.collaborationType}
            
            Mesaj:
            ${formData.message}
            ${attachmentInfo}
        `;window.location.href=`mailto:support@pro-lance.com?subject=${encodeURIComponent(emailSubject)}&body=${encodeURIComponent(emailBody)}`;const successMessage=document.createElement('div');successMessage.className='form-message success';successMessage.style.backgroundColor='#d4edda';successMessage.style.color='#155724';successMessage.style.padding='1rem';successMessage.style.borderRadius='4px';successMessage.style.marginTop='1rem';successMessage.textContent=messages.success;this.insertAdjacentElement('afterend',successMessage);this.reset();form.querySelectorAll('input, textarea, select').forEach(input=>{input.style.borderColor='';input.style.backgroundColor='';if(input.nextElementSibling?.classList.contains('error-message')){input.nextElementSibling.remove();}});if(fileInfo){fileInfo.textContent='';}
setTimeout(()=>successMessage.remove(),5000);});});document.addEventListener('DOMContentLoaded',function(){initMobileMenu();});function initMobileMenu(){const hamburger=document.querySelector('.hamburger');const nav=document.querySelector('.nav');const body=document.body;if(hamburger&&nav){hamburger.replaceWith(hamburger.cloneNode(true));const newHamburger=document.querySelector('.hamburger');newHamburger.addEventListener('click',function(e){e.stopPropagation();newHamburger.classList.toggle('active');nav.classList.toggle('active');if(nav.classList.contains('active')){body.style.overflow='hidden';}else{body.style.overflow='';}});document.addEventListener('click',function(event){if(nav.classList.contains('active')&&!newHamburger.contains(event.target)&&!nav.contains(event.target)){newHamburger.classList.remove('active');nav.classList.remove('active');body.style.overflow='';}});window.addEventListener('resize',function(){if(window.innerWidth>992&&nav.classList.contains('active')){newHamburger.classList.remove('active');nav.classList.remove('active');body.style.overflow='';}});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&nav.classList.contains('active')){newHamburger.classList.remove('active');nav.classList.remove('active');body.style.overflow='';}});}}